// TikTok 用户名提取逻辑 - 排除大写字母版
const items = $input.all();
const extractedData = [];

// 通用称呼列表（需要排除的）
const GENERIC_GREETINGS = [
  'dear', 'hi', 'hello', 'sir', 'madam', 'team', 'all', 'everyone', 
  'folks', 'guys', 'ladies', 'gentlemen', 'friend', 'friends',
  'colleague', 'colleagues', 'there', 'support', 'admin', 'manager'
];

// 特别排除的用户名
const EXCLUDED_USERNAMES = ['hani', 'hani@inspiremarks.com'];

// 格式化邮件内容 - 去除 Markdown 和 HTML，保留纯文本
function formatEmailContent(content) {
  if (!content) return '';

  let formatted = content;

  // 1. 去除 HTML 标签
  formatted = formatted.replace(/<[^>]*>/gi, '');

  // 2. 去除 Markdown 格式
  // 移除粗体 **text** 和 __text__
  formatted = formatted.replace(/\*\*(.*?)\*\*/g, '$1');
  formatted = formatted.replace(/__(.*?)__/g, '$1');

  // 移除斜体 *text* 和 _text_
  formatted = formatted.replace(/\*(.*?)\*/g, '$1');
  formatted = formatted.replace(/_(.*?)_/g, '$1');

  // 移除代码块 ```code```
  formatted = formatted.replace(/```[\s\S]*?```/g, '');

  // 移除行内代码 `code`
  formatted = formatted.replace(/`([^`]*)`/g, '$1');

  // 移除链接 [text](url)
  formatted = formatted.replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1');

  // 移除图片 ![alt](url)
  formatted = formatted.replace(/!\[([^\]]*)\]\([^\)]+\)/g, '$1');

  // 移除标题标记 # ## ###
  formatted = formatted.replace(/^#{1,6}\s+/gm, '');

  // 移除列表标记 - * +
  formatted = formatted.replace(/^[\s]*[-\*\+]\s+/gm, '');

  // 移除数字列表 1. 2. 3.
  formatted = formatted.replace(/^[\s]*\d+\.\s+/gm, '');

  // 移除引用 >
  formatted = formatted.replace(/^>\s*/gm, '');

  // 移除水平线 --- *** ___
  formatted = formatted.replace(/^[-\*_]{3,}$/gm, '');

  // 3. 清理多余的空白字符
  // 将多个连续空格替换为单个空格
  formatted = formatted.replace(/\s+/g, ' ');

  // 将多个连续换行替换为单个换行
  formatted = formatted.replace(/\n\s*\n/g, '\n');

  // 去除首尾空白
  formatted = formatted.trim();

  return formatted;
}

// 计算两个用户名的相似度（Jaccard相似度）
function calculateSimilarity(str1, str2) {
  const set1 = new Set(str1.toLowerCase());
  const set2 = new Set(str2.toLowerCase());
  const intersection = new Set([...set1].filter(x => set2.has(x)));
  const union = new Set([...set1, ...set2]);
  return intersection.size / union.size;
}

// 检查用户名是否相似（重复率高的）
function isSimilarUsername(username1, username2) {
  // 如果两个用户名长度差异很大，不太可能是同一个
  if (Math.abs(username1.length - username2.length) > 8) {
    return false;
  }

  // 计算相似度
  const similarity = calculateSimilarity(username1, username2);

  // 如果相似度超过70%，认为是相似用户名
  if (similarity > 0.7) {
    // 检查是否包含关系（如 morgan 和 morganvg12）
    if (username1.includes(username2) || username2.includes(username1)) {
      return true;
    }
    // 检查前缀匹配（如 morgan 和 morganvg12）
    const shorter = username1.length < username2.length ? username1 : username2;
    const longer = username1.length < username2.length ? username2 : username1;
    if (longer.startsWith(shorter) && longer.length - shorter.length <= 5) {
      return true;
    }
  }

  return false;
}

// 检查用户名是否包含数字或特殊字符
function hasSpecialChars(username) {
  // 检查是否包含数字、下划线、点号等特殊字符
  return /[0-9._\-]/.test(username);
}

// 检查用户名是否包含大写字母
function hasUppercase(username) {
  return /[A-Z]/.test(username);
}

// 用户名优先级排序函数
function compareUsernames(user1, user2) {
  const username1 = user1.username;
  const username2 = user2.username;

  const hasSpecial1 = hasSpecialChars(username1);
  const hasSpecial2 = hasSpecialChars(username2);

  // 第一优先级：包含数字或特殊字符的用户名优先
  if (hasSpecial1 && !hasSpecial2) {
    return -1; // user1 优先
  }
  if (!hasSpecial1 && hasSpecial2) {
    return 1;  // user2 优先
  }

  // 第二优先级：如果都包含或都不包含特殊字符，选择较长的
  if (username1.length !== username2.length) {
    return username2.length - username1.length; // 较长的优先
  }

  // 如果长度也相同，保持原有顺序
  return 0;
}

for (const item of items) {
  const email = item.json;
  let emailContent = '';

  // 获取邮件内容 - 优先从 text 字段获取
  if (email.text) {
    emailContent = email.text;
  } else if (email.textPlain) {
    emailContent = email.textPlain;
  } else if (email.textHtml) {
    // 简单的HTML标签清理
    emailContent = email.textHtml.replace(/<[^>]*>/g, ' ');
  } else if (email.snippet) {
    emailContent = email.snippet;
  } else if (email['内容']) {
    emailContent = email['内容'];
  }

  // 格式化邮件内容
  const formattedContent = formatEmailContent(emailContent);

  // 调试信息
  console.log('处理邮件:', email.subject);
  console.log('原始内容长度:', emailContent.length);
  console.log('格式化后内容长度:', formattedContent.length);
  console.log('格式化后内容前300字符:', formattedContent.substring(0, 300));

  // 提取 "Hi xxx" 模式的用户名
  const hiPattern = /hi\s+([a-zA-Z0-9_.-]+)[\s,!]/gi;
  const matches = formattedContent.matchAll(hiPattern);

  const extractedUsernames = [];

  for (const match of matches) {
    const username = match[1].toLowerCase().trim();
    const originalUsername = match[1]; // 保持原始大小写用于检查
    console.log('找到用户名:', username, '(原始:', originalUsername, ')');

    // 检查是否包含大写字母（新增过滤条件）
    if (hasUppercase(originalUsername)) {
      console.log('用户名包含大写字母，被过滤:', originalUsername);
      continue;
    }

    // 排除通用称呼和特定用户名
    if (!GENERIC_GREETINGS.includes(username) && 
        !EXCLUDED_USERNAMES.includes(username) &&
        username.length > 1 && 
        username.length < 30) {
      extractedUsernames.push({
        username: username,
        original: originalUsername // 保持原始大小写
      });
      console.log('用户名有效:', username);
    } else {
      console.log('用户名被过滤:', username);
    }
  }

  // 智能去重：使用优先级规则
  const uniqueUsernames = [];

  for (const userInfo of extractedUsernames) {
    const username = userInfo.username;
    let shouldAdd = true;
    let replaceIndex = -1;

    // 检查是否与已处理的用户名相似
    for (let i = 0; i < uniqueUsernames.length; i++) {
      const existingUser = uniqueUsernames[i];
      if (isSimilarUsername(username, existingUser.username)) {
        console.log('发现相似用户名:', username, '与', existingUser.username);

        // 比较优先级
        const comparison = compareUsernames(userInfo, existingUser);
        if (comparison < 0) {
          // 新用户名优先级更高，替换旧的
          console.log('新用户名优先级更高:', username, '替换', existingUser.username);
          replaceIndex = i;
          shouldAdd = true;
        } else {
          // 旧用户名优先级更高或相等，不添加新的
          console.log('保留现有用户名:', existingUser.username, '过滤掉:', username);
          shouldAdd = false;
        }
        break;
      }
    }

    if (shouldAdd) {
      if (replaceIndex >= 0) {
        // 替换现有用户名
        uniqueUsernames[replaceIndex] = userInfo;
        console.log('替换用户名:', userInfo.username);
      } else {
        // 添加新用户名
        uniqueUsernames.push(userInfo);
        console.log('添加唯一用户名:', username);
      }
    }
  }

  // 为每个去重后的用户名创建记录
  for (const userInfo of uniqueUsernames) {
    extractedData.push({
      json: {
        emailSubject: email.subject || '邮件主题',
        emailFrom: email.from?.value?.[0]?.address || email['From'] || '未知发件人',
        emailDate: email.date || email['时间'] || new Date().toISOString(),
        extractedUsername: userInfo.original, // 使用原始大小写
        tiktokUrl: `https://www.tiktok.com/@${userInfo.original}`,
        extractedAt: new Date().toISOString(),
        emailSnippet: formattedContent.substring(0, 200) + (formattedContent.length > 200 ? '...' : ''), // 格式化后的内容摘要
        formattedContent: formattedContent, // 完整的格式化内容
        originalEmail: email
      }
    });
  }
}

// 如果没有提取到用户名，记录这个情况
if (extractedData.length === 0) {
  return [{
    json: {
      error: '未找到TikTok用户名',
      emailCount: items.length,
      extractedAt: new Date().toISOString(),
      debugInfo: '请检查邮件内容是否包含 Hi xxx 格式（不包含大写字母）'
    }
  }];
}

// 确保返回正确的格式
return extractedData;

